import Ajv from "ajv";
import schemas from "./schemas.json";

// ajv 8.17.1 compiles the JSON Schema that FastAPI exports for each Pydantic model (schemas.json is
// generated by `node generate-client.mjs`; do not edit it). strict is off because the OpenAPI
// document carries keywords ajv does not know (for example "title"-only objects and "examples").
const ajv = new Ajv({ strict: false, allErrors: false });
const cache = new Map<string, ReturnType<typeof ajv.compile>>();

/**
 * Validate a value against a Pydantic model's schema, by the model's class name. Returns null when
 * the value satisfies every constraint the schema states, or a short description of the first one it breaks.
 */
export function validateSchema(model: string, value: unknown): string | null {
  let check = cache.get(model);
  if (!check) {
    check = ajv.compile({ $ref: `#/components/schemas/${model}`, components: { schemas } });
    cache.set(model, check);
  }
  if (check(value)) return null;
  const e = check.errors?.[0];
  return e ? `${e.instancePath || "/"} ${e.message ?? "is invalid"}` : "is invalid";
}
